pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 tokenId, uint256 quantity) public {
        // keep quantity > 0 and tokenId in a reasonable range for setup
        vm.assume(quantity > 0 && quantity <= type(uint96).max);
        vm.assume(tokenId < 20);

        // set up a game item so balance can be non-zero
        // we need a neuron instance to satisfy mint requirements
        address neuronAddr = address(new NeuronMock());
        c.instantiateNeuronContract(neuronAddr);

        // create a simple game item with no finite supply, transferable, zero price, large daily allowance
        c.createGameItem("TestItem", "", false, true, 10000, 0, uint16(quantity + 1000));

        address account = address(0x1234);
        vm.prank(account);
        c.mint(tokenId, quantity);

        uint256 balance = c.balanceOf(account, tokenId);
        assertTrue(balance == quantity);
    }
}

contract NeuronMock {
    mapping(address => uint256) private _balances;

    function approveSpender(address owner, uint256 amount) external {
        // mock allowance
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 bal = _balances[from];
        require(bal >= amount, "insufficient balance");
        unchecked {
            _balances[from] = bal - amount;
        }
        _balances[to] += amount;
        return true;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
    }

    // fallback to fund the mock if needed
    fallback() external payable {}
}

