import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 tokenId, uint256 quantity) public {
        // create minimal environment: a game item that can be minted, a Neuron-like mock for purchase
        quantity = bound(quantity, 1, type(uint96).max);

        // We need a mock Neuron that succeeds on approveSpender and transferFrom
        MockNeuron neuron = new MockNeuron();
        c.instantiateNeuronContract(address(neuron));

        // Give the buyer enough mock NRN
        vm.deal(address(this), 0);
        neuron.setBalance(address(this), type(uint256).max);

        // Create a single game item with finiteSupply = false, price = 1
        c.createGameItem("TestItem", "https://test", false, true, 1000, 1, 10000);
        tokenId = bound(tokenId, 0, c.uniqueTokensOutstanding() - 1);

        // Mint the token to acquire balance
        vm.prank(address(this));
        c.mint(tokenId, quantity);

        // Assert that balanceOf returns the minted quantity
        uint256 balance = c.balanceOf(address(this), tokenId);
        assertTrue(balance == quantity);
    }
}

