pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(uint256 tokenId, uint256 quantity, address recipient) public {
        // Restrict to admissible domain: tokenId must fit a typical range, recipient not zero, quantity > 0
        vm.assume(tokenId < 100);
        vm.assume(recipient != address(0));
        vm.assume(quantity > 0 && quantity < 1_000_000 ether);

        // Admin sets up a game item so we can mint
        vm.startPrank(address(this));
        c.adjustAdminAccess(address(this), true);
