        c.createGameItem("TestItem", "ipfs://test", false, true, 10000, 0, 100);
        vm.stopPrank();

        // Mint tokens to recipient
        vm.prank(address(this));
        c.mint(tokenId, quantity);

        // Check balanceOf via the public view function
        uint256 balance = c.balanceOf(recipient, tokenId);

        // The reference returns the minted quantity; the mutant returns 0.
        assertEq(balance, quantity, "balanceOf must reflect minted tokens");
    }
}

